describe('Checkbox Toggle Functionality', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/checkboxes');
  });

  it('should have correct initial checkbox states', () => {
    cy.get('input[type="checkbox"]').should('have.length', 2);
    cy.get('input[type="checkbox"]').eq(0).should('not.be.checked');
    cy.get('input[type="checkbox"]').eq(1).should('be.checked');
  });

  it('should check first checkbox and verify both are checked', () => {
    cy.get('input[type="checkbox"]').eq(0).click();
    cy.get('input[type="checkbox"]').eq(0).should('be.checked');
    cy.get('input[type="checkbox"]').eq(1).should('be.checked');
  });

  it('should uncheck second checkbox and leave only first checked', () => {
    cy.get('input[type="checkbox"]').eq(0).click();
    cy.get('input[type="checkbox"]').eq(1).click();
    cy.get('input[type="checkbox"]').eq(0).should('be.checked');
    cy.get('input[type="checkbox"]').eq(1).should('not.be.checked');
  });

  it('should handle multiple toggle operations correctly', () => {
    const firstCheckbox = cy.get('input[type="checkbox"]').eq(0);
    const secondCheckbox = cy.get('input[type="checkbox"]').eq(1);

    firstCheckbox.click();
    firstCheckbox.should('be.checked');
    secondCheckbox.should('be.checked');

    secondCheckbox.click();
    firstCheckbox.should('be.checked');
    secondCheckbox.should('not.be.checked');

    firstCheckbox.click();
    firstCheckbox.should('not.be.checked');
    secondCheckbox.should('not.be.checked');
  });
});
